-- 完整版本包含多套法规集、法规和法规参数,以及系统法规
select * from workset where id in (0,3566,4397,5017,5267,5269,5278,5279,5283,5286,5287);

select * from rule_set where workset_id in (0,3566,4397,5017,5267,5269,5278,5279,5283,5286,5287);

select * from rule where id in (select rule_id from rule_set where workset_id in (0,3566,4397,5017,5267,5269,5278,5279,5283,5286,5287)) or owner ='S' order by instance, id;

-- 注意rule_parameter可能有垃圾数据
select * from rule_parameter where rule_id in (select id from rule where id in (select rule_id from rule_set where workset_id in (0,3566,4397,5017,5267,5269,5278,5279,5283,5286,5287)) or owner ='S') order by id;

select * from rule_parameter;
-- 查询垃圾数据
select * from rule_parameter where id not in (select id from rule_parameter where rule_id in (select id from rule where id in (select rule_id from rule_set where workset_id in (0,3566,4397,5017,5267,5269,5278,5279,5283,5286,5287)) or owner ='S') );


